package agent

import "time"

// Hypothesis represents a reasoned testable theory generated by the AI Planner.
type Hypothesis struct {
	ID              string    `json:"id"`
	Context         string    `json:"context"`          // e.g. "REST API + numeric ID"
	TargetURL       string    `json:"target_url"`
	Theory          string    `json:"theory"`           // e.g. "IDOR in /api/users/{id}"
	PreferredAction string    `json:"preferred_action"`  // e.g. "Send differential authorization probe"
	ToolSelected    string    `json:"tool_selected"`    // e.g. "http_probe", "nuclei"
	Confidence      float64   `json:"confidence"`       // Historical success probability (0-100)
	PriorityScore   float64   `json:"priority_score"`
	CreatedAt       time.Time `json:"created_at"`
}

// CandidateBug represents an observation produced by the AI Analyzer prior to verification.
type CandidateBug struct {
	HypothesisID string    `json:"hypothesis_id"`
	Title        string    `json:"title"`
	CWE          string    `json:"cwe"`
	Severity     string    `json:"severity"`
	TargetURL    string    `json:"target_url"`
	RawEvidence  string    `json:"raw_evidence"`
	ToolPath     []string  `json:"tool_path"`
	DiscoveredAt time.Time `json:"discovered_at"`
}

// VerificationResult represents the Verifier's determination.
type VerificationResult struct {
	Confirmed        bool     `json:"confirmed"`
	Reason           string   `json:"reason"`
	ReproducedProof  string   `json:"reproduced_proof"`
	ActualIssue      string   `json:"actual_issue"`
	CVSSScore        float64  `json:"cvss_score"`
	RemediationSteps []string `json:"remediation_steps"`
}
